  /** Send it with POST /incidents, or POST /incident-screening/dismiss */
  screening_key: string;
  kind: "ReturnToTheatre" | "Readmission" | "Death";
  found_at: string;
  patient_id: number;
  mrn: string;
  patient_name: string;
  admission_id: number | null;
  booking_id: number | null;
  death_id: number | null;
  suggested_type_code: string;
  suggested_type_name: string;
  detail: string;
}

