/** What the records show that may be a sentinel event — GET /api/v1/incident-screening (who may call: holders of incident.view). */
export function screeningList(): Promise<ScreeningItemOut[]> {
  return api<ScreeningItemOut[]>("GET", `/incident-screening`, undefined);
}

/** Dismiss a screening item with the reason — POST /api/v1/incident-screening/dismiss (who may call: holders of incident.manage). */
export function dismiss(body: DismissIn): Promise<DismissedItemOut> {
  return api<DismissedItemOut>("POST", `/incident-screening/dismiss`, body);
}

/** Report an incident, an adverse event or a near miss — POST /api/v1/incidents (who may call: holders of incident.report). */
export function reportIncidents(body: IncidentIn): Promise<IncidentDetailOut> {
  return api<IncidentDetailOut>("POST", `/incidents`, body, { idempotent: true });
}

/** What to report: the incident types — GET /api/v1/incident-types (who may call: any logged-in user). */
export function listTypes(query?: { area?: "Clinical" | "Medication" | "Anaesthesia" | "Surgery" | "Diagnostics" | "Transfusion" | "Infection" | "MotherAndBaby" | "Behaviour" | "Facility" | "Occupational" | null; active_only?: boolean }): Promise<IncidentTypeOut[]> {
  return api<IncidentTypeOut[]>("GET", withQuery(`/incident-types`, query), undefined);
}

/** Find a staff member for a form (badge facts only) — GET /api/v1/staff/lookup (who may call: any logged-in user). */
export function lookupStaff(query: { q: string; department_id?: number | null; license_type?: "PMDC" | "PNC" | null; limit?: number }): Promise<StaffLookupOut[]> {
  return api<StaffLookupOut[]>("GET", withQuery(`/staff/lookup`, query), undefined);
}

/** Departments — GET /api/v1/admin/departments (who may call: any logged-in user). */
export function departments(): Promise<DepartmentOut[]> {
  return api<DepartmentOut[]>("GET", `/admin/departments`, undefined);
}

/** Live bed matrix (counts per ward + optional bed list) — GET /api/v1/beds/matrix (who may call: holders of ipd.bed.view or cssd.operate or infection.control.manage or complaint.manage or incident.view or facility.drill.manage or roster.manage.all or facility.equipment.manage or pharmacy.storage.record). */
export function bedMatrix(query?: { include_beds?: boolean }): Promise<BedMatrixOut> {
  return api<BedMatrixOut>("GET", withQuery(`/beds/matrix`, query), undefined);
}

/** Formulary search with live stock colour — GET /api/v1/drugs/search (who may call: holders of pharmacy.formulary.view). */
export function searchDrugs(query?: { q?: string; limit?: number }): Promise<DrugStockOut[]> {
  return api<DrugStockOut[]>("GET", withQuery(`/drugs/search`, query), undefined);
}
